    const size_t numOfAttachmentLayerParamsToTest = numOfImageLayerParamsToTest - 2;

    const VkExtent3D imageDimensions[] = {{256, 1, 1},   {256, 256, 1},  {256, 256, 16}, {200, 1, 1},
