                    m_context.getTestContext().getLog()
                        << tcu::TestLog::Message << "Bad color at (" << x << ", " << y << "): " << fb[idx].x() << " "
                        << fb[idx].y() << " " << fb[idx].z() << tcu::TestLog::EndMessage;
