            << "} sb_out;\n"
            << "void main (void) {\n"
            << "    uvec3 size           = gl_NumWorkGroups * gl_WorkGroupSize;\n"
            << "    uint numValuesPerInv = uint(ub_in.values.length()) / (size.x*size.y*size.z);\n"
            << "    uint groupNdx        = size.x*size.y*gl_GlobalInvocationID.z + size.x*gl_GlobalInvocationID.y + "
