    DataTest &operator=(const DataTest &other);

    typedef void(GLW_APIENTRY *PFNGLNAMEDBUFFERDATA)(glw::GLuint buffer, glw::GLsizeiptr size, const glw::GLvoid *data,
                                                     glw::GLenum usage);
