};


// === Member function implementations ===

AttributeBindingTest::AttributeBindingTest(deqp::Context &context)
    : deqp::TestCase(context, "vertex_arrays_attribute_binding", "Vertex Array Objects Attribute Binding Test")
    , m_po(0)
    , m_vao(0)
    , m_bo_array(0)
    , m_bo_xfb(0)
