{
    const Functions &gl = m_context.getRenderContext().getFunctions();

    gl.bindAttribLocation(program.m_id, m_goten_location, "goten");
    GLU_EXPECT_NO_ERROR(gl.getError(), "BindAttribLocation");

    program.Link(gl, program.m_id);

