    {
        GLboolean b;
        GLint i;
        GLfloat f;
        GLint64 i64;

        glGetIntegerv(pname, &i);
        if (i < min_value)
            return false;

        glGetBooleanv(pname, &b);
        if (b != (i ? GL_TRUE : GL_FALSE))
            return false;

        glGetFloatv(pname, &f);
        if (f < static_cast<GLfloat>(min_value))
            return false;

        glGetInteger64v(pname, &i64);
        if (i64 < static_cast<GLint64>(min_value))
