        GLboolean b;

        glGetIntegeri_v(GL_IMAGE_BINDING_NAME, unit, &i);
        if (static_cast<GLuint>(i) != texture)
        {
            m_context.getTestContext().getLog() << tcu::TestLog::Message << "GL_IMAGE_BINDING_NAME is " << i
                                                << " should be " << texture << tcu::TestLog::EndMessage;
            return false;
