    {
        CreateFullViewportQuad(&m_vao, &m_vbo, NULL);

        if (!Write(GL_RGBA32F, vec4(1.0f, 2.0f, 3.0f, 4.0f), vec4(1.0f, 2.0f, 3.0f, 4.0f)))
            return ERROR;
