            return ERROR;
        if (!Write(GL_RG8UI, uvec4(0, 1, 2, 3), uvec4(0, 1, 0, 1)))
            return ERROR;
        if (!Write(GL_R8UI, uvec4(7, 2, 3, 4), uvec4(7, 0, 0, 1)))
            return ERROR;

        if (!Write(GL_RGBA16, vec4(1.0f), vec4(1.0f)))
            return ERROR;
        if (!Write(GL_RGB10_A2, vec4(1.0f), vec4(1.0f)))
