        std::ostringstream s;
        s << "[";
        for (int i = 0; i < 4; ++i)
            s << v[i] << (i == 3 ? "" : ",");
        s << "]";
        return s.str();
    }

    template <typename T>
    bool CompareValues(T *map_data, int kSize, const T &expected_value, GLenum internalformat = 0, int layers = 1)
    {
