                        NotSupportedError,
                        "VkShaderAtomicFloat16: 16-bit floating point buffer min/max atomic operation not supported");
                }
            }
        }
        if (m_atomicOp == ATOMIC_OP_EXCHANGE)
        {
            if (m_shaderType.isSharedLike())
