                    << tcu::toHex(out_data[i]) << " should be " << tcu::toHex(in_data[i]) << tcu::TestLog::EndMessage;
                status = false;
            }
            else
            {
            }
        }
        glUnmapBuffer(GL_SHADER_STORAGE_BUFFER);
        if (!status)
            return ERROR;
        return NO_ERROR;
    }

    virtual long Cleanup()
    {
        glUseProgram(0);
        glDeleteProgram(m_program);
        glDeleteBuffers(2, m_buffer);
        return NO_ERROR;
    }
};

