                VK_DESCRIPTOR_POOL_CREATE_FREE_DESCRIPTOR_SET_BIT, // VkDescriptorPoolCreateFlags flags;
                1u,                                                // uint32_t maxSets;
                DE_LENGTH_OF_ARRAY(descriptorTypes),               // uint32_t count;
                descriptorTypes                                    // const VkDescriptorTypeCount* pTypeCount
