                0,                                       // uint32_t destBinding;
                0,                                       // uint32_t destArrayElement;
                1u,                                      // uint32_t count;
                VK_DESCRIPTOR_TYPE_UNIFORM_TEXEL_BUFFER, // VkDescriptorType descriptorType;
