        const GLint csize      = base_level ? 64 : 32;
        GLint size             = csize;
        GLenum target          = GL_TEXTURE_2D;
        GLenum tex_type        = GL_FLOAT;

        glGenTextures(1, &tex);
        glBindTexture(target, tex);
        for (int i = 0; size > 0; ++i, size /= 2)
