class IncompleteTexture : public PlainGatherFloat2DRgba
{
    virtual void Init()
    {
        CreateTexture2D();
        glTexImage2D(GL_TEXTURE_2D, 1, GL_RGBA32F, 1, 1, 0, GL_RGBA, GL_FLOAT, 0);
    }

    virtual Vec4 Expected()
    {
        return Vec4(0);
    }
};

