            glBufferSubData(GL_ARRAY_BUFFER, 40 + kStride, sizeof(d), d);
        }
        {
            GLfloat d[] = {-46.0f, 47.0f, -48.0f, 49.0f};
            glBufferSubData(GL_ARRAY_BUFFER, 56 + kStride, sizeof(d), d);
        }
        {
