                    << " " << datai[i][3] << ", datai should be: " << expected_datai[i][0] << " "
                    << expected_datai[i][1] << " " << expected_datai[i][2] << " " << expected_datai[i][3]
                    << ", index is: " << i << tcu::TestLog::EndMessage;
