                                                              const char *test_description)
    : deqp::TestCase(context, test_name, test_description)
    , m_context(context)
    , m_program_id_generate(0)
    , m_program_id_draw(0)
    , m_vao_id(0)
    , m_xfb_id(0)
    , m_bo_id_xfb(0)
    , m_bo_id_uniform(0)
    , m_fbo_id(0)
    , m_rbo_id(0)
    , m_glGetUniformBlockIndex(nullptr)
    , m_glUniformBlockBinding(nullptr)
{
}

