        .setupFragmentShaderState(pipelineLayout, VK_NULL_HANDLE, 0u, fragModule)
        .setupFragmentOutputState(VK_NULL_HANDLE)
        .setMonolithicPipelineLayout(pipelineLayout)
        .buildPipeline();

