// === Methods ===

void ShaderObjectLinkCase::checkSupport(Context &context) const
{
    context.requireDeviceFunctionality("VK_EXT_shader_object");

    if (m_params.shaders.tesellation_control != UNUSED || m_params.shaders.tesellation_evaluation != UNUSED ||
        (m_params.nextStages.vertNextStage | vk::VK_SHADER_STAGE_TESSELLATION_CONTROL_BIT) > 0)
        context.requireDeviceCoreFeature(vkt::DEVICE_CORE_FEATURE_TESSELLATION_SHADER);

    if (m_params.shaders.geometry != UNUSED ||
        (m_params.nextStages.vertNextStage | vk::VK_SHADER_STAGE_GEOMETRY_BIT) > 0 ||
        (m_params.nextStages.teseNextStage | vk::VK_SHADER_STAGE_GEOMETRY_BIT) > 0)
        context.requireDeviceCoreFeature(vkt::DEVICE_CORE_FEATURE_GEOMETRY_SHADER);
}

void ShaderObjectLinkCase::initPrograms(vk::SourceCollections &programCollection) const
{
    vk::addBasicShaderObjectShaders(programCollection);

    std::stringstream vert;
    std::stringstream tese;
    std::stringstream geom;
    std::stringstream comp;

    vert << "#version 450\n"
         << "layout (binding = 0) buffer Result { uint result[4]; };\n"
         << "void main() {\n"
         << "    vec2 pos = vec2(float(gl_VertexIndex & 1), float((gl_VertexIndex >> 1) & 1));\n"
         << "    gl_Position = vec4(pos - 0.5f, 0.0f, 1.0f);\n"
         << "    result[gl_VertexIndex] = gl_VertexIndex + 1;\n"
         << "}\n";

    tese << "#version 450\n"
         << "\n"
         << "layout(quads, equal_spacing) in;\n"
         << "layout (binding = 0) buffer Result { uint result[4]; };\n"
         << "\n"
         << "void main (void)\n"
         << "{\n"
         << "    float u = gl_TessCoord.x;\n"
         << "    float v = gl_TessCoord.y;\n"
         << "    float omu = 1.0f - u;\n"
         << "    float omv = 1.0f - v;\n"
         << "    gl_Position = omu * omv * gl_in[0].gl_Position + u * omv * gl_in[2].gl_Position + u * v * "
            "gl_in[3].gl_Position + omu * v * gl_in[1].gl_Position;\n"
         << "    gl_Position.x *= 1.5f;\n"
         << "    if (gl_PrimitiveID == 0) {\n"
         << "        result[0] = 1;\n"
         << "        result[1] = 2;\n"
         << "        result[2] = 3;\n"
         << "        result[3] = 4;\n"
         << "    }\n"
         << "}\n";

    geom << "#version 450\n"
         << "layout(triangles) in;\n"
         << "layout(triangle_strip, max_vertices = 4) out;\n"
         << "layout (binding = 0) buffer Result { uint result[4]; };\n"
         << "\n"
         << "void main(void)\n"
         << "{\n"
         << "    gl_Position = gl_in[0].gl_Position;\n"
         << "    gl_Position.y *= 1.5f;\n"
         << "    gl_Position.z = 0.5f;\n"
         << "    EmitVertex();\n"
         << "    gl_Position = gl_in[1].gl_Position;\n"
         << "    gl_Position.y *= 1.5f;\n"
         << "    gl_Position.z = 0.5f;\n"
         << "    EmitVertex();\n"
         << "    gl_Position = gl_in[2].gl_Position;\n"
         << "    gl_Position.y *= 1.5f;\n"
         << "    gl_Position.z = 0.5f;\n"
         << "    EmitVertex();\n"
         << "    EndPrimitive();\n"
         << "    if (gl_InvocationID == 0) {\n"
         << "        result[0] = 1;\n"
         << "        result[1] = 2;\n"
         << "        result[2] = 3;\n"
         << "        result[3] = 4;\n"
         << "    }\n"
         << "}\n";

    comp << "#version 450\n"
         << "layout(local_size_x=16, local_size_x=16, local_size_x=1) in;\n"
         << "void main() {\n"
         << "}\n";

    programCollection.glslSources.add("vert2") << glu::VertexSource(vert.str());
    programCollection.glslSources.add("tese2") << glu::TessellationEvaluationSource(tese.str());
    programCollection.glslSources.add("geom2") << glu::GeometrySource(geom.str());
    programCollection.glslSources.add("comp2") << glu::ComputeSource(comp.str());
}

