    }

    vertexShaderSource << version << "precision highp float;\n"
                       << extensions << attributeDeclaration.str()
                       << "layout(set = 0, binding = 0, std430) buffer outBuffer\n"
                          "{\n"
                          "\t"
                       << outType << " outData[" << (m_numVertices * numValues) * m_numInstances
