                            "layout(location = 0) out vec4 fragColor;\n"
                            "void main (void)\n"
                            "{\n"
                            "\tfragColor = vec4(1.0);\n"
                            "}\n";

    programCollection.glslSources.add("fragment") << glu::FragmentSource(fragmentShaderSource.str());
}

