BuffersTest::BuffersTest(deqp::Context &context)
    : deqp::TestCase(context, "xfb_buffers", "Transform Feedback Buffers Test")
    , m_gl_getTransformFeedbacki_v(nullptr)
    , m_gl_getTransformFeedbacki64_v(nullptr)
