class FunctionalTest : public deqp::TestCase
{
public:
    /* Public member functions */
    FunctionalTest(deqp::Context &context);

    virtual tcu::TestNode::IterateResult iterate();

private:
    /* Private member functions */
    FunctionalTest(const FunctionalTest &other);
    FunctionalTest &operator=(const FunctionalTest &other);

    /* Function pointers type definitions and declarations. */
    typedef void(GLW_APIENTRY *GetTransformFeedbackiv_ProcAddress)(glw::GLuint xfb, glw::GLenum pname,
                                                                   glw::GLint *param);
    typedef void(GLW_APIENTRY *TransformFeedbackBufferBase_ProcAddress)(glw::GLuint xfb, glw::GLuint index,
                                                                        glw::GLuint buffer);

    GetTransformFeedbackiv_ProcAddress m_gl_getTransformFeedbackiv;
    TransformFeedbackBufferBase_ProcAddress m_gl_TransformFeedbackBufferBase;

    /* Private member variables. */
    glw::GLuint m_xfb_dsa;
    glw::GLuint m_bo;
    glw::GLuint m_po;
    glw::GLuint m_vao;

    /* Private member functions. */
    void prepareFunctionPointers();
    void prepareTransformFeedback();
    void prepareBuffer();
    void prepareProgram();
    void prepareVertexArrayObject();

    bool draw();
    bool testTransformFeedbackStatus(glw::GLenum parameter_name, glw::GLint expected_value);
    bool verifyBufferContent();

    void clean();

    /* Private static variables. */
    static const glw::GLuint s_bo_size;
    static const glw::GLchar s_vertex_shader[];
    static const glw::GLchar s_fragment_shader[];
    static const glw::GLchar *const s_xfb_varying;
};


// === Member function implementations ===

FunctionalTest::FunctionalTest(deqp::Context &context)
    : deqp::TestCase(context, "xfb_functional", "Transform Feedback Functional Test")
    , m_gl_getTransformFeedbackiv(nullptr)
    , m_gl_TransformFeedbackBufferBase(nullptr)
    , m_xfb_dsa(0)
    , m_bo(0)
    , m_po(0)
    , m_vao(0)
{
    /* Intentionally left blank. */
}

tcu::TestNode::IterateResult FunctionalTest::iterate()
{
    /* Get context setup. */
    bool is_at_least_gl_45 = (glu::contextSupports(m_context.getRenderContext().getType(), glu::ApiType::core(4, 5)));
    bool is_arb_direct_state_access = m_context.getContextInfo().isExtensionSupported("GL_ARB_direct_state_access");

    if ((!is_at_least_gl_45) && (!is_arb_direct_state_access))
    {
        m_testCtx.setTestResult(QP_TEST_RESULT_NOT_SUPPORTED, "Not Supported");

        return STOP;
    }

    /* Running tests. */
    bool is_ok    = true;
    bool is_error = false;

    try
    {
        prepareFunctionPointers();
        prepareTransformFeedback();
        prepareBuffer();
        prepareProgram();
        prepareVertexArrayObject();

        is_ok &= draw();
        is_ok &= verifyBufferContent();
    }
    catch (...)
    {
        is_ok    = false;
        is_error = true;
    }

    /* Releasing GL objects. */
    clean();

    /* Result's setup. */
    if (is_ok)
    {
        m_testCtx.setTestResult(QP_TEST_RESULT_PASS, "Pass");
    }
    else
    {
        if (is_error)
        {
            m_testCtx.setTestResult(QP_TEST_RESULT_INTERNAL_ERROR, "Error");
        }
        else
        {
            m_testCtx.setTestResult(QP_TEST_RESULT_FAIL, "Fail");
        }
    }

    return STOP;
}

void FunctionalTest::prepareFunctionPointers()
{
    /* Shortcut for GL functionality */
    const glw::Functions &gl = m_context.getRenderContext().getFunctions();

    /* Fetching function pointers. */
    m_gl_getTransformFeedbackiv      = (GetTransformFeedbackiv_ProcAddress)gl.getTransformFeedbackiv;
    m_gl_TransformFeedbackBufferBase = (TransformFeedbackBufferBase_ProcAddress)gl.transformFeedbackBufferBase;

    if ((nullptr == m_gl_getTransformFeedbackiv) || (nullptr == m_gl_TransformFeedbackBufferBase))
    {
        m_context.getTestContext().getLog()
            << tcu::TestLog::Message << "Function pointers are set to NULL values." << tcu::TestLog::EndMessage;

        throw 0;
    }
}

void FunctionalTest::prepareTransformFeedback()
{
    /* Shortcut for GL functionality */
    const glw::Functions &gl = m_context.getRenderContext().getFunctions();

    /* XFB object creation. */
    gl.createTransformFeedbacks(1, &m_xfb_dsa);
    GLU_EXPECT_NO_ERROR(gl.getError(), "glCreateTransformFeedbacks have failed");
}

void FunctionalTest::prepareBuffer()
{
    /* Shortcut for GL functionality */
    const glw::Functions &gl = m_context.getRenderContext().getFunctions();

    /* Buffer creation and memory allocation. */
    gl.genBuffers(1, &m_bo);
    GLU_EXPECT_NO_ERROR(gl.getError(), "glGenBuffers have failed");

    gl.bindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER, m_bo);
    GLU_EXPECT_NO_ERROR(gl.getError(), "glBindBuffer have failed");

    gl.bufferData(GL_TRANSFORM_FEEDBACK_BUFFER, s_bo_size, nullptr, GL_DYNAMIC_COPY);
    GLU_EXPECT_NO_ERROR(gl.getError(), "glBufferData have failed");

    gl.bindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER, 0);
    GLU_EXPECT_NO_ERROR(gl.getError(), "glBindBuffer have failed");

    /* Bind buffer to xfb object (using direct state access function). */
    m_gl_TransformFeedbackBufferBase(m_xfb_dsa, 0, m_bo);
    GLU_EXPECT_NO_ERROR(gl.getError(), "glTransformFeedbackBufferBase have failed");
}

void FunctionalTest::prepareProgram()
{
    /* Shortcut for GL functionality */
    const glw::Functions &gl = m_context.getRenderContext().getFunctions();

    struct Shader
    {
        glw::GLchar const *const source;
        glw::GLenum const type;
        glw::GLuint id;
    } shader[] = {{s_vertex_shader, GL_VERTEX_SHADER, 0}, {s_fragment_shader, GL_FRAGMENT_SHADER, 0}};

    glw::GLuint const shader_count = sizeof(shader) / sizeof(shader[0]);

    try
    {
        /* Create program. */
        m_po = gl.createProgram();
        GLU_EXPECT_NO_ERROR(gl.getError(), "glCreateProgram call failed.");

        /* Shader compilation. */

        for (glw::GLuint i = 0; i < shader_count; ++i)
        {
            if (nullptr != shader[i].source)
            {
                shader[i].id = gl.createShader(shader[i].type);

                GLU_EXPECT_NO_ERROR(gl.getError(), "glCreateShader call failed.");

                gl.attachShader(m_po, shader[i].id);

                GLU_EXPECT_NO_ERROR(gl.getError(), "glAttachShader call failed.");

                gl.shaderSource(shader[i].id, 1, &(shader[i].source), NULL);

                GLU_EXPECT_NO_ERROR(gl.getError(), "glShaderSource call failed.");

                gl.compileShader(shader[i].id);

                GLU_EXPECT_NO_ERROR(gl.getError(), "glCompileShader call failed.");

                glw::GLint status = GL_FALSE;

                gl.getShaderiv(shader[i].id, GL_COMPILE_STATUS, &status);
                GLU_EXPECT_NO_ERROR(gl.getError(), "glGetShaderiv call failed.");

                if (GL_FALSE == status)
                {
                    glw::GLint log_size = 0;
                    gl.getShaderiv(shader[i].id, GL_INFO_LOG_LENGTH, &log_size);
                    GLU_EXPECT_NO_ERROR(gl.getError(), "glGetShaderiv call failed.");

                    glw::GLchar *log_text = new glw::GLchar[log_size];

                    gl.getShaderInfoLog(shader[i].id, log_size, NULL, &log_text[0]);

                    m_context.getTestContext().getLog()
                        << tcu::TestLog::Message << "Shader compilation has failed.\n"
                        << "Shader type: " << glu::getShaderTypeStr(shader[i].type) << "\n"
                        << "Shader compilation error log:\n"
                        << log_text << "\n"
                        << "Shader source code:\n"
                        << shader[i].source << "\n"
                        << tcu::TestLog::EndMessage;

                    delete[] log_text;

                    GLU_EXPECT_NO_ERROR(gl.getError(), "glGetShaderInfoLog call failed.");

                    throw 0;
                }
            }
        }

        /* Transform Feedback setup. */
        gl.transformFeedbackVaryings(m_po, 1, &s_xfb_varying, GL_INTERLEAVED_ATTRIBS);
        GLU_EXPECT_NO_ERROR(gl.getError(), "glTransformFeedbackVaryings call failed.");

        /* Link. */
        gl.linkProgram(m_po);

        GLU_EXPECT_NO_ERROR(gl.getError(), "glTransformFeedbackVaryings call failed.");

        glw::GLint status = GL_FALSE;

        gl.getProgramiv(m_po, GL_LINK_STATUS, &status);

        if (GL_TRUE == status)
        {
            for (glw::GLuint i = 0; i < shader_count; ++i)
            {
                if (shader[i].id)
                {
                    gl.detachShader(m_po, shader[i].id);

                    GLU_EXPECT_NO_ERROR(gl.getError(), "glDetachShader call failed.");
                }
            }
        }
        else
        {
            glw::GLint log_size = 0;

            gl.getProgramiv(m_po, GL_INFO_LOG_LENGTH, &log_size);

            GLU_EXPECT_NO_ERROR(gl.getError(), "glGetProgramiv call failed.");

            glw::GLchar *log_text = new glw::GLchar[log_size];

            gl.getProgramInfoLog(m_po, log_size, NULL, &log_text[0]);

            m_context.getTestContext().getLog() << tcu::TestLog::Message << "Program linkage has failed due to:\n"
                                                << log_text << "\n"
                                                << tcu::TestLog::EndMessage;

            delete[] log_text;

            GLU_EXPECT_NO_ERROR(gl.getError(), "glGetProgramInfoLog call failed.");

            throw 0;
        }
    }
    catch (...)
    {
        if (m_po)
        {
            gl.deleteProgram(m_po);

            m_po = 0;
        }
    }

    for (glw::GLuint i = 0; i < shader_count; ++i)
    {
        if (0 != shader[i].id)
        {
            gl.deleteShader(shader[i].id);

            shader[i].id = 0;
        }
    }

    if (m_po)
    {
        gl.useProgram(m_po);
        GLU_EXPECT_NO_ERROR(gl.getError(), "glUseProgram call failed.");
    }

    if (0 == m_po)
    {
        throw 0;
    }
}

