class SpecConstantTest : public TestCase
{
public:
    SpecConstantTest(tcu::TestContext &testCtx,
                     const PipelineConstructionType pipelineType, //!< how pipeline is constructed
                     const VkShaderStageFlagBits stage,           //!< which shader stage is tested
                     const CaseDefinition &caseDef);

    void initPrograms(SourceCollections &programCollection) const;
    TestInstance *createInstance(Context &context) const;
    virtual void checkSupport(Context &context) const;

private:
    const PipelineConstructionType m_pipelineConstructionType;
    const VkShaderStageFlagBits m_stage;
    const CaseDefinition m_caseDef;
}

// === Methods ===

SpecConstantTest::SpecConstantTest(tcu::TestContext &testCtx, const PipelineConstructionType pipelineType,
                                   const VkShaderStageFlagBits stage, const CaseDefinition &caseDef)
    : TestCase(testCtx, caseDef.name)
    , m_pipelineConstructionType(pipelineType)
    , m_stage(stage)
    , m_caseDef(caseDef)
{
}

void SpecConstantTest::initPrograms(SourceCollections &programCollection) const
{
    // Always add vertex and fragment to graphics stages
    VkShaderStageFlags requiredStages = m_stage;

    if (requiredStages & VK_SHADER_STAGE_ALL_GRAPHICS)
        requiredStages |= VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT;

    if (requiredStages & (VK_SHADER_STAGE_TESSELLATION_CONTROL_BIT | VK_SHADER_STAGE_TESSELLATION_EVALUATION_BIT))
        requiredStages |= VK_SHADER_STAGE_TESSELLATION_CONTROL_BIT | VK_SHADER_STAGE_TESSELLATION_EVALUATION_BIT;

    // Either graphics or compute must be defined, but not both
    DE_ASSERT(((requiredStages & VK_SHADER_STAGE_ALL_GRAPHICS) != 0) !=
              ((requiredStages & VK_SHADER_STAGE_COMPUTE_BIT) != 0));

    // Extensions needed for some tests.
    std::ostringstream extStream;
    if (m_caseDef.requirements & FEATURE_SHADER_INT_64)
        extStream << "#extension GL_EXT_shader_explicit_arithmetic_types_int64 : require\n";
    if (m_caseDef.requirements & FEATURE_SHADER_INT_16)
        extStream << "#extension GL_EXT_shader_explicit_arithmetic_types_int16 : require\n";
    if (m_caseDef.requirements & FEATURE_SHADER_INT_8)
        extStream << "#extension GL_EXT_shader_explicit_arithmetic_types_int8 : require\n";
    if (m_caseDef.requirements & FEATURE_SHADER_FLOAT_16)
        extStream << "#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require\n";
    const std::string extensions = extStream.str();

    // This makes glslang avoid the UniformAndStorage* capabilities.
    const vk::ShaderBuildOptions buildOptions(programCollection.usedVulkanVersion, SPIRV_VERSION_1_3, 0u);

    if (requiredStages & VK_SHADER_STAGE_VERTEX_BIT)
    {
        const bool useSpecConst = (m_stage == VK_SHADER_STAGE_VERTEX_BIT);
        std::ostringstream src;
        src << glu::getGLSLVersionDeclaration(glu::GLSL_VERSION_450) << "\n"
            << extensions << "layout(location = 0) in highp vec4 position;\n"
            << "\n"
            << "out " << s_perVertexBlock << ";\n"
            << "\n"
            << (useSpecConst ? generateSpecConstantCode(m_caseDef.specConstants) : "")
            << (useSpecConst ? generateSSBOCode(m_caseDef.ssboCode) : "")
            << (useSpecConst ? m_caseDef.globalCode + "\n" : "") << "void main (void)\n"
            << "{\n"
            << (useSpecConst ? m_caseDef.mainCode + "\n" : "") << "    gl_Position = position;\n"
            << "}\n";

        programCollection.glslSources.add("vert") << glu::VertexSource(src.str()) << buildOptions;
    }

    if (requiredStages & VK_SHADER_STAGE_FRAGMENT_BIT)
    {
        const bool useSpecConst = (m_stage == VK_SHADER_STAGE_FRAGMENT_BIT);
        std::ostringstream src;
        src << glu::getGLSLVersionDeclaration(glu::GLSL_VERSION_450) << "\n"
            << extensions << "layout(location = 0) out highp vec4 fragColor;\n"
            << "\n"
            << (useSpecConst ? generateSpecConstantCode(m_caseDef.specConstants) : "")
            << (useSpecConst ? generateSSBOCode(m_caseDef.ssboCode) : "")
            << (useSpecConst ? m_caseDef.globalCode + "\n" : "") << "void main (void)\n"
            << "{\n"
            << (useSpecConst ? m_caseDef.mainCode + "\n" : "") << "    fragColor = vec4(1.0, 1.0, 0.0, 1.0);\n"
            << "}\n";

        programCollection.glslSources.add("frag") << glu::FragmentSource(src.str()) << buildOptions;
    }

    if (requiredStages & VK_SHADER_STAGE_TESSELLATION_CONTROL_BIT)
    {
        const bool useSpecConst = (m_stage == VK_SHADER_STAGE_TESSELLATION_CONTROL_BIT);
        std::ostringstream src;
        src << glu::getGLSLVersionDeclaration(glu::GLSL_VERSION_450) << "\n"
            << extensions << "layout(vertices = 3) out;\n"
            << "\n"
            << "in " << s_perVertexBlock << " gl_in[gl_MaxPatchVertices];\n"
            << "\n"
            << "out " << s_perVertexBlock << " gl_out[];\n"
            << "\n"
            << (useSpecConst ? generateSpecConstantCode(m_caseDef.specConstants) : "")
            << (useSpecConst ? generateSSBOCode(m_caseDef.ssboCode) : "")
            << (useSpecConst ? m_caseDef.globalCode + "\n" : "") << "void main (void)\n"
            << "{\n"
            << (useSpecConst ? m_caseDef.mainCode + "\n" : "")
            << "    gl_out[gl_InvocationID].gl_Position = gl_in[gl_InvocationID].gl_Position;\n"
            << "    if (gl_InvocationID == 0)\n"
            << "    {\n"
            << "        gl_TessLevelInner[0] = 3;\n"
            << "        gl_TessLevelOuter[0] = 2;\n"
            << "        gl_TessLevelOuter[1] = 2;\n"
            << "        gl_TessLevelOuter[2] = 2;\n"
            << "    }\n"
            << "}\n";

        programCollection.glslSources.add("tesc") << glu::TessellationControlSource(src.str()) << buildOptions;
    }

    if (requiredStages & VK_SHADER_STAGE_TESSELLATION_EVALUATION_BIT)
    {
        const bool useSpecConst = (m_stage == VK_SHADER_STAGE_TESSELLATION_EVALUATION_BIT);
        std::ostringstream src;
        src << glu::getGLSLVersionDeclaration(glu::GLSL_VERSION_450) << "\n"
            << extensions << "layout(triangles, equal_spacing, ccw) in;\n"
            << "\n"
            << "in " << s_perVertexBlock << " gl_in[gl_MaxPatchVertices];\n"
            << "\n"
            << "out " << s_perVertexBlock << ";\n"
            << "\n"
            << (useSpecConst ? generateSpecConstantCode(m_caseDef.specConstants) : "")
            << (useSpecConst ? generateSSBOCode(m_caseDef.ssboCode) : "")
            << (useSpecConst ? m_caseDef.globalCode + "\n" : "") << "void main (void)\n"
            << "{\n"
            << (useSpecConst ? m_caseDef.mainCode + "\n" : "")
            << "    vec3 p0 = gl_TessCoord.x * gl_in[0].gl_Position.xyz;\n"
            << "    vec3 p1 = gl_TessCoord.y * gl_in[1].gl_Position.xyz;\n"
            << "    vec3 p2 = gl_TessCoord.z * gl_in[2].gl_Position.xyz;\n"
            << "    gl_Position = vec4(p0 + p1 + p2, 1.0);\n"
            << "}\n";

        programCollection.glslSources.add("tese") << glu::TessellationEvaluationSource(src.str()) << buildOptions;
    }

    if (requiredStages & VK_SHADER_STAGE_GEOMETRY_BIT)
    {
        const bool useSpecConst = (m_stage == VK_SHADER_STAGE_GEOMETRY_BIT);
        std::ostringstream src;
        src << glu::getGLSLVersionDeclaration(glu::GLSL_VERSION_450) << "\n"
            << extensions << "layout(triangles) in;\n"
            << "layout(triangle_strip, max_vertices = 3) out;\n"
            << "\n"
            << "in " << s_perVertexBlock << " gl_in[];\n"
            << "\n"
            << "out " << s_perVertexBlock << ";\n"
            << "\n"
            << (useSpecConst ? generateSpecConstantCode(m_caseDef.specConstants) : "")
            << (useSpecConst ? generateSSBOCode(m_caseDef.ssboCode) : "")
            << (useSpecConst ? m_caseDef.globalCode + "\n" : "") << "void main (void)\n"
            << "{\n"
            << (useSpecConst ? m_caseDef.mainCode + "\n" : "") << "    gl_Position = gl_in[0].gl_Position;\n"
            << "    EmitVertex();\n"
            << "\n"
            << "    gl_Position = gl_in[1].gl_Position;\n"
            << "    EmitVertex();\n"
            << "\n"
            << "    gl_Position = gl_in[2].gl_Position;\n"
            << "    EmitVertex();\n"
            << "\n"
            << "    EndPrimitive();\n"
            << "}\n";

        programCollection.glslSources.add("geom") << glu::GeometrySource(src.str()) << buildOptions;
    }

    if (requiredStages & VK_SHADER_STAGE_COMPUTE_BIT)
    {
        std::ostringstream src;
        src << glu::getGLSLVersionDeclaration(glu::GLSL_VERSION_450) << "\n"
            << extensions
            // Don't define work group size, use the default or specialization constants
            << "\n"
            << generateSpecConstantCode(m_caseDef.specConstants) << generateSSBOCode(m_caseDef.ssboCode)
            << m_caseDef.globalCode + "\n"
            << "void main (void)\n"
            << "{\n"
            << m_caseDef.mainCode << "}\n";

        programCollection.glslSources.add("comp") << glu::ComputeSource(src.str()) << buildOptions;
    }
}

void SpecConstantTest::checkSupport(Context &context) const
{
    requireFeatures(context, m_caseDef.requirements | getShaderStageRequirements(m_stage));
    checkPipelineConstructionRequirements(context.getInstanceInterface(), context.getPhysicalDevice(),
                                          m_pipelineConstructionType);
}

TestInstance *SpecConstantTest::createInstance(Context &context) const
{
    if (m_stage & VK_SHADER_STAGE_COMPUTE_BIT)
        return new ComputeTestInstance(context, m_pipelineConstructionType, m_caseDef.ssboSize, m_caseDef.specConstants,
                                       m_caseDef.expectedValues, m_caseDef.packData);
    else
        return new GraphicsTestInstance(context, m_pipelineConstructionType, m_caseDef.ssboSize,
                                        m_caseDef.specConstants, m_caseDef.expectedValues, m_stage, m_caseDef.packData);
}

// === TestInstance ===

class ComputeTestInstance : public TestInstance
{
public:
    ComputeTestInstance(Context &context, PipelineConstructionType pipelineConstructionType,
                        const VkDeviceSize ssboSize, const std::vector<SpecConstant> &specConstants,
                        const std::vector<OffsetValue> &expectedValues, bool packData);

    tcu::TestStatus iterate(void);

private:
    const PipelineConstructionType m_pipelineConstructionType;
    const VkDeviceSize m_ssboSize;
    const std::vector<SpecConstant> m_specConstants;
    const std::vector<OffsetValue> m_expectedValues;
    const bool m_packData;
}

// === TestInstance Methods ===

virtual ~ComputeTestInstance(void) = default

void ComputeTestInstance::buildBuffers(void)
{
    const DeviceInterface &vk = m_context.getDeviceInterface();
    const VkDevice vkDevice   = m_context.getDevice();

    // Create buffer object, allocate storage, and generate input data
    const VkDeviceSize size = sizeof(tcu::Vec4) * 128u;
    m_inputBuf = createBufferAndBindMemory(m_context, size, VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, &m_inputBufferAlloc);

    // Initialize input buffer
    tcu::Vec4 *pVec = reinterpret_cast<tcu::Vec4 *>(m_inputBufferAlloc->getHostPtr());
    for (uint32_t ndx = 0u; ndx < 128u; ndx++)
    {
        for (uint32_t component = 0u; component < 4u; component++)
            pVec[ndx][component] = (float)(ndx * (component + 1u));
    }
    flushAlloc(vk, vkDevice, *m_inputBufferAlloc);

    // Clear the output buffer
    for (uint32_t ndx = 0; ndx < PIPELINE_NDX_COUNT; ndx++)
    {
        m_outputBuf[ndx] =
            createBufferAndBindMemory(m_context, size, VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, &m_outputBufferAlloc[ndx]);

        pVec = reinterpret_cast<tcu::Vec4 *>(m_outputBufferAlloc[ndx]->getHostPtr());

        for (uint32_t i = 0; i < (size / sizeof(tcu::Vec4)); i++)
            pVec[i] = tcu::Vec4(0.0f);

        flushAlloc(vk, vkDevice, *m_outputBufferAlloc[ndx]);
    }
}

void ComputeTestInstance::buildDescriptorSets(uint32_t ndx)
{
    const DeviceInterface &vk = m_context.getDeviceInterface();
    const VkDevice vkDevice   = m_context.getDevice();

    // Create descriptor set layout
    DescriptorSetLayoutBuilder descLayoutBuilder;

    for (uint32_t bindingNdx = 0u; bindingNdx < 2u; bindingNdx++)
        descLayoutBuilder.addSingleBinding(VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, VK_SHADER_STAGE_COMPUTE_BIT);

    m_descriptorSetLayout[ndx] = descLayoutBuilder.build(vk, vkDevice);

    std::vector<VkDescriptorBufferInfo> descriptorInfos;
    descriptorInfos.push_back(makeDescriptorBufferInfo(*m_inputBuf, 0u, sizeof(tcu::Vec4) * 128u));
    descriptorInfos.push_back(makeDescriptorBufferInfo(*m_outputBuf[ndx], 0u, sizeof(tcu::Vec4) * 128u));

    // Create descriptor pool
    m_descriptorPool[ndx] = DescriptorPoolBuilder()
                                .addType(VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 2u)
                                .build(vk, vkDevice, VK_DESCRIPTOR_POOL_CREATE_FREE_DESCRIPTOR_SET_BIT, 1u);

    // Create descriptor set
    const VkDescriptorSetAllocateInfo descriptorSetAllocInfo = {
        VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO, // VkStructureType                 sType;
        nullptr,                                        // const void*                     pNext;
        *m_descriptorPool[ndx],                         // VkDescriptorPool                descriptorPool;
        1u,                                             // uint32_t                        setLayoutCount;
        &m_descriptorSetLayout[ndx].get(),              // const VkDescriptorSetLayout*    pSetLayouts;
    };
    m_descriptorSet[ndx] = allocateDescriptorSet(vk, vkDevice, &descriptorSetAllocInfo);

    DescriptorSetUpdateBuilder builder;
    for (uint32_t descriptorNdx = 0u; descriptorNdx < 2u; descriptorNdx++)
    {
        builder.writeSingle(*m_descriptorSet[ndx], DescriptorSetUpdateBuilder::Location::binding(descriptorNdx),
                            VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, &descriptorInfos[descriptorNdx]);
    }
    builder.update(vk, vkDevice);
}

void ComputeTestInstance::buildShader(void)
{
    const DeviceInterface &vk = m_context.getDeviceInterface();
    const VkDevice vkDevice   = m_context.getDevice();

    // Create compute shader
    VkShaderModuleCreateInfo shaderModuleCreateInfo = {
        VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO,                    // VkStructureType             sType;
        nullptr,                                                        // const void*                 pNext;
        0u,                                                             // VkShaderModuleCreateFlags   flags;
        m_context.getBinaryCollection().get("basic_compute").getSize(), // uintptr_t                   codeSize;
        (uint32_t *)m_context.getBinaryCollection()
            .get("basic_compute")
            .getBinary(), // const uint32_t*             pCode;
    };
    m_computeShaderModule = createShaderModule(vk, vkDevice, &shaderModuleCreateInfo);
}

void ComputeTestInstance::buildPipeline(uint32_t ndx)
{
    const DeviceInterface &vk = m_context.getDeviceInterface();
    const VkDevice vkDevice   = m_context.getDevice();

    // Create compute pipeline layout
    const VkPipelineLayoutCreateInfo pipelineLayoutCreateInfo = {
        VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO, // VkStructureType                 sType;
        nullptr,                                       // const void*                     pNext;
        0u,                                            // VkPipelineLayoutCreateFlags     flags;
        1u,                                            // uint32_t                        setLayoutCount;
        &m_descriptorSetLayout[ndx].get(),             // const VkDescriptorSetLayout*    pSetLayouts;
        0u,                                            // uint32_t                        pushConstantRangeCount;
        nullptr,                                       // const VkPushConstantRange*      pPushConstantRanges;
    };

    m_pipelineLayout[ndx] = createPipelineLayout(vk, vkDevice, &pipelineLayoutCreateInfo);

    const VkPipelineShaderStageCreateInfo stageCreateInfo = {
        VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO, // VkStructureType                     sType;
        nullptr,                                             // const void*                         pNext;
        0u,                                                  // VkPipelineShaderStageCreateFlags    flags;
        VK_SHADER_STAGE_COMPUTE_BIT,                         // VkShaderStageFlagBits               stage;
        *m_computeShaderModule,                              // VkShaderModule                      module;
        "main",                                              // const char*                         pName;
        nullptr,                                             // const VkSpecializationInfo*         pSpecializationInfo;
    };

    VkPipelineCreateFlags2CreateInfoKHR pipelineFlags2CreateInfo = initVulkanStructure();
    pipelineFlags2CreateInfo.flags                               = VK_PIPELINE_CREATE_2_CAPTURE_DATA_BIT_KHR;
    const void *pNext = (m_param->getMode() == TestMode::BINARY) ? &pipelineFlags2CreateInfo : nullptr;
    VkComputePipelineCreateInfo pipelineCreateInfo{
        VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO, // VkStructureType sType;
        pNext,                                          // const void* pNext;
        0,                                              // VkPipelineCreateFlags flags;
        stageCreateInfo,                                // VkPipelineShaderStageCreateInfo stage;
        *m_pipelineLayout[ndx],                         // VkPipelineLayout layout;
        VK_NULL_HANDLE,                                 // VkPipeline basePipelineHandle;
        0u,                                             // int32_t basePipelineIndex;
    };

    if (m_param->getMode() == TestMode::CACHE)
        m_pipeline[ndx] = createComputePipeline(vk, vkDevice, *m_cache, &pipelineCreateInfo);
    else
    {
        if (ndx == PIPELINE_NDX_NO_BLOBS)
        {
            auto pipelineKey = m_binaries[0].getPipelineKey(&pipelineCreateInfo);
            if (pipelineKey.keySize == 0)
                TCU_FAIL("vkGetPipelineKeyKHR returned keySize == 0");

            // create pipeline
            m_pipeline[ndx] = createComputePipeline(vk, vkDevice, VK_NULL_HANDLE, &pipelineCreateInfo);

            // prepare pipeline binaries
            m_binaries[0].createPipelineBinariesFromPipeline(*m_pipeline[ndx]);

            if (m_param->getUseBinariesFromBinaryData())
            {
                // read binaries data out of the device
                std::vector<VkPipelineBinaryDataKHR> pipelineDataInfo;
                std::vector<std::vector<uint8_t>> pipelineDataBlob;
                m_binaries[0].getPipelineBinaryData(pipelineDataInfo, pipelineDataBlob);

                // clear pipeline binaries objects
                m_binaries[0].deletePipelineBinariesKeepKeys();

                // recreate binaries from data blobs
                m_binaries[0].createPipelineBinariesFromBinaryData(pipelineDataInfo);
            }
        }
        else
        {
            // create pipeline using binary data and use pipelineCreateInfo with no shader stage
            VkPipelineBinaryInfoKHR pipelineBinaryInfo = m_binaries[0].preparePipelineBinaryInfo();
            pipelineCreateInfo.pNext                   = &pipelineBinaryInfo;
            pipelineCreateInfo.stage.module            = VK_NULL_HANDLE;
            m_pipeline[ndx] = createComputePipeline(vk, vkDevice, VK_NULL_HANDLE, &pipelineCreateInfo);
        }
    }
}

ComputeTestInstance::ComputeTestInstance(Context &context, const TestParam *param) : BaseTestInstance(context, param)
{
    buildBuffers();

    buildDescriptorSets(PIPELINE_NDX_NO_BLOBS);

    buildDescriptorSets(PIPELINE_NDX_USE_BLOBS);

    buildShader();

    buildPipeline(PIPELINE_NDX_NO_BLOBS);

    buildPipeline(PIPELINE_NDX_USE_BLOBS);
}

void ComputeTestInstance::prepareCommandBuffer(void)
{
    const DeviceInterface &vk = m_context.getDeviceInterface();

    beginCommandBuffer(vk, *m_cmdBuffer, 0u);

    for (uint32_t ndx = 0; ndx < PIPELINE_NDX_COUNT; ndx++)
    {
        vk.cmdBindPipeline(*m_cmdBuffer, VK_PIPELINE_BIND_POINT_COMPUTE, *m_pipeline[ndx]);
        vk.cmdBindDescriptorSets(*m_cmdBuffer, VK_PIPELINE_BIND_POINT_COMPUTE, *m_pipelineLayout[ndx], 0u, 1u,
                                 &m_descriptorSet[ndx].get(), 0u, nullptr);
        vk.cmdDispatch(*m_cmdBuffer, 128u, 1u, 1u);
    }

    endCommandBuffer(vk, *m_cmdBuffer);
}

tcu::TestStatus ComputeTestInstance::verifyTestResult(void)
{
    const DeviceInterface &vk = m_context.getDeviceInterface();
    const VkDevice vkDevice   = m_context.getDevice();

    // Read the content of output buffers
    invalidateAlloc(vk, vkDevice, *m_outputBufferAlloc[PIPELINE_NDX_NO_BLOBS]);

    invalidateAlloc(vk, vkDevice, *m_outputBufferAlloc[PIPELINE_NDX_USE_BLOBS]);
    // Compare the content
    uint8_t *bufNoCache = reinterpret_cast<uint8_t *>(m_outputBufferAlloc[PIPELINE_NDX_NO_BLOBS]->getHostPtr());
    uint8_t *bufCached  = reinterpret_cast<uint8_t *>(m_outputBufferAlloc[PIPELINE_NDX_USE_BLOBS]->getHostPtr());
    for (uint32_t ndx = 0u; ndx < sizeof(tcu::Vec4) * 128u; ndx++)
    {
        if (bufNoCache[ndx] != bufCached[ndx])
        {
            return tcu::TestStatus::fail("Output buffers w/o pipeline blobs mismatch.");
        }
    }

    return tcu::TestStatus::pass("Output buffers w/o pipeline blobs match.");
}

virtual ~ComputeTestInstance(void) = default

void ComputeTestInstance::buildDescriptorSets(uint32_t ndx)
{
    const DeviceInterface &vk = m_context.getDeviceInterface();
    const VkDevice vkDevice   = m_context.getDevice();

    // Create descriptor set layout
    DescriptorSetLayoutBuilder descLayoutBuilder;
    for (uint32_t bindingNdx = 0u; bindingNdx < 2u; bindingNdx++)
        descLayoutBuilder.addSingleBinding(VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, VK_SHADER_STAGE_COMPUTE_BIT);
    m_descriptorSetLayout[ndx] = descLayoutBuilder.build(vk, vkDevice);
}

void ComputeTestInstance::buildShader(uint32_t ndx)
{
    const DeviceInterface &vk = m_context.getDeviceInterface();
    const VkDevice vkDevice   = m_context.getDevice();

    std::string shader_name("basic_compute_");

    shader_name += (ndx == PIPELINE_NDX_DERIVATIVE) ? "2" : "1";

    // Create compute shader
    VkShaderModuleCreateInfo shaderModuleCreateInfo = {
        VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO,                              // VkStructureType sType;
        nullptr,                                                                  // const void* pNext;
        0u,                                                                       // VkShaderModuleCreateFlags flags;
        m_context.getBinaryCollection().get(shader_name).getSize(),               // uintptr_t codeSize;
        (uint32_t *)m_context.getBinaryCollection().get(shader_name).getBinary(), // const uint32_t* pCode;
    };
    m_computeShaderModule[ndx] = createShaderModule(vk, vkDevice, &shaderModuleCreateInfo);
}

void ComputeTestInstance::buildPipeline(const TestParam *param, uint32_t ndx)
{
    const DeviceInterface &vk           = m_context.getDeviceInterface();
    const VkDevice vkDevice             = m_context.getDevice();
    const VkBool32 zeroOutFeedbackCount = param->isZeroOutFeedbackCount();

    deMemset(&m_pipelineCreationFeedback[ndx], 0, sizeof(VkPipelineCreationFeedbackEXT));
    deMemset(&m_pipelineStageCreationFeedback[ndx], 0, sizeof(VkPipelineCreationFeedbackEXT));

    VkPipelineCreateFlags2CreateInfoKHR pipelineFlags2CreateInfo = initVulkanStructure();
    pipelineFlags2CreateInfo.flags                               = VK_PIPELINE_CREATE_2_CAPTURE_DATA_BIT_KHR;

    VkPipelineCreationFeedbackCreateInfoEXT pipelineCreationFeedbackCreateInfo{
        VK_STRUCTURE_TYPE_PIPELINE_CREATION_FEEDBACK_CREATE_INFO_EXT, // VkStructureType sType;
        nullptr,                                                      // const void * pNext;
        &m_pipelineCreationFeedback[ndx],     // VkPipelineCreationFeedbackEXT* pPipelineCreationFeedback;
        zeroOutFeedbackCount ? 0u : 1u,       // uint32_t pipelineStageCreationFeedbackCount;
        &m_pipelineStageCreationFeedback[ndx] // VkPipelineCreationFeedbackEXT* pPipelineStageCreationFeedbacks;
    };

    // Create compute pipeline layout
    const VkPipelineLayoutCreateInfo pipelineLayoutCreateInfo{
        VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO, // VkStructureType sType;
        nullptr,                                       // const void* pNext;
        0u,                                            // VkPipelineLayoutCreateFlags flags;
        1u,                                            // uint32_t setLayoutCount;
        &m_descriptorSetLayout[ndx].get(),             // const VkDescriptorSetLayout* pSetLayouts;
        0u,                                            // uint32_t pushConstantRangeCount;
        nullptr,                                       // const VkPushConstantRange* pPushConstantRanges;
    };

    m_pipelineLayout[ndx] = createPipelineLayout(vk, vkDevice, &pipelineLayoutCreateInfo);

    const VkPipelineShaderStageCreateInfo stageCreateInfo = {
        VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO, // VkStructureType sType;
        nullptr,                                             // const void* pNext;
        0u,                                                  // VkPipelineShaderStageCreateFlags flags;
        VK_SHADER_STAGE_COMPUTE_BIT,                         // VkShaderStageFlagBits stage;
        *m_computeShaderModule[ndx],                         // VkShaderModule module;
        "main",                                              // const char* pName;
        nullptr,                                             // const VkSpecializationInfo* pSpecializationInfo;
    };

    VkComputePipelineCreateInfo pipelineCreateInfo = {
        VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO, // VkStructureType sType;
        &pipelineCreationFeedbackCreateInfo,            // const void* pNext;
        0u,                                             // VkPipelineCreateFlags flags;
        stageCreateInfo,                                // VkPipelineShaderStageCreateInfo stage;
        *m_pipelineLayout[ndx],                         // VkPipelineLayout layout;
        VK_NULL_HANDLE,                                 // VkPipeline basePipelineHandle;
        0u,                                             // int32_t basePipelineIndex;
    };

    if (ndx != PIPELINE_NDX_DERIVATIVE)
    {
        pipelineCreateInfo.flags = VK_PIPELINE_CREATE_ALLOW_DERIVATIVES_BIT;
    }

    if (ndx == PIPELINE_NDX_DERIVATIVE)
    {
        pipelineCreateInfo.flags              = VK_PIPELINE_CREATE_DERIVATIVE_BIT;
        pipelineCreateInfo.basePipelineHandle = m_pipeline[PIPELINE_NDX_NO_BLOBS];
        pipelineCreateInfo.basePipelineIndex  = -1;
    }

    if (ndx == PIPELINE_NDX_USE_BLOBS && !param->isDelayedDestroy())
    {
        // Destroy the NO_BLOBS pipeline to check that the cached/binary one really hits cache,
        // except for the case where we're testing cache hit of a pipeline still active.
        vk.destroyPipeline(vkDevice, m_pipeline[PIPELINE_NDX_NO_BLOBS], nullptr);
    }

    if (m_param->getMode() == TestMode::CACHE)
        vk.createComputePipelines(vkDevice, *m_cache, 1u, &pipelineCreateInfo, nullptr, &m_pipeline[ndx]);
    else
    {
        // we need to switch to using VkPipelineCreateFlags2KHR and also include flags that were specified in pipelineCreateInfo
        pipelineFlags2CreateInfo.flags |= static_cast<VkPipelineCreateFlags2KHR>(pipelineCreateInfo.flags);
        pipelineCreationFeedbackCreateInfo.pNext = &pipelineFlags2CreateInfo;

        if (ndx == PIPELINE_NDX_NO_BLOBS)
        {
            // create pipeline
            vk.createComputePipelines(vkDevice, *m_cache, 1u, &pipelineCreateInfo, nullptr, &m_pipeline[ndx]);

            // prepare pipeline binaries
            m_binaries[0].createPipelineBinariesFromPipeline(m_pipeline[ndx]);
        }
        else
        {
            // create pipeline using binary data and use pipelineCreateInfo with no shader stage
            VkPipelineBinaryInfoKHR pipelineBinaryInfo = m_binaries[0].preparePipelineBinaryInfo();
            pipelineCreateInfo.pNext                   = &pipelineBinaryInfo;
            pipelineCreateInfo.stage.module            = VK_NULL_HANDLE;
            vk.createComputePipelines(vkDevice, *m_cache, 1u, &pipelineCreateInfo, nullptr, &m_pipeline[ndx]);
        }
    }

    if (ndx != PIPELINE_NDX_NO_BLOBS)
    {
        // Destroy the pipeline as soon as it is created, except the NO_BLOBS because
        // it is needed as a base pipeline for the derivative case.
        vk.destroyPipeline(vkDevice, m_pipeline[ndx], nullptr);

        if (ndx == PIPELINE_NDX_USE_BLOBS && param->isDelayedDestroy())
        {
            // Destroy the pipeline we didn't destroy earlier for the isDelayedDestroy case.
            vk.destroyPipeline(vkDevice, m_pipeline[PIPELINE_NDX_NO_BLOBS], nullptr);
        }
    }
}

ComputeTestInstance::ComputeTestInstance(Context &context, const TestParam *param) : BaseTestInstance(context, param)
{
    for (uint32_t ndx = 0; ndx < PIPELINE_NDX_COUNT; ndx++)
    {
        buildDescriptorSets(ndx);
        buildShader(ndx);
        buildPipeline(param, ndx);
    }
}

tcu::TestStatus ComputeTestInstance::verifyTestResult(void)
{
    tcu::TestLog &log          = m_context.getTestContext().getLog();
    bool durationZeroWarning   = false;
    bool cachedPipelineWarning = false;

    for (uint32_t ndx = 0; ndx < PIPELINE_NDX_COUNT; ndx++)
    {
        std::ostringstream message;
        message << getCaseStr(ndx);

        // No need to check per stage status as it is compute pipeline (only one stage) and Vulkan spec mentions that:
        // "One common scenario for an implementation to skip per-stage feedback is when
        // VK_PIPELINE_CREATION_FEEDBACK_APPLICATION_PIPELINE_CACHE_HIT_BIT_EXT is set in pPipelineCreationFeedback."
        //
        // Check first that the no cached pipeline was missed in the pipeline cache

        // According to the spec:
        // "An implementation should write pipeline creation feedback to pPipelineCreationFeedback and
        //    may write pipeline stage creation feedback to pPipelineStageCreationFeedbacks."
        if (!(m_pipelineCreationFeedback[ndx].flags & VK_PIPELINE_CREATION_FEEDBACK_VALID_BIT_EXT))
        {
            // According to the spec:
            // "If the VK_PIPELINE_CREATION_FEEDBACK_VALID_BIT_EXT is not set in flags, an implementation
            //    must not set any other bits in flags, and all other VkPipelineCreationFeedbackEXT data members are undefined."
            if (m_pipelineCreationFeedback[ndx].flags)
            {
                std::ostringstream errorMsg;
                errorMsg << ": Creation feedback is not valid but there are other flags written";
                return tcu::TestStatus::fail(errorMsg.str());
            }
            message << "\t\t Pipeline Creation Feedback data is not valid\n";
        }
        else
        {
            if (m_param->isCacheDisabled() && m_pipelineCreationFeedback[ndx].flags &
                                                  VK_PIPELINE_CREATION_FEEDBACK_APPLICATION_PIPELINE_CACHE_HIT_BIT_EXT)
            {
                message << ": feedback indicates pipeline hit cache when it shouldn't";
                return tcu::TestStatus::fail(message.str());
            }

            if (ndx == PIPELINE_NDX_NO_BLOBS &&
                m_pipelineCreationFeedback[ndx].flags &
                    VK_PIPELINE_CREATION_FEEDBACK_APPLICATION_PIPELINE_CACHE_HIT_BIT_EXT)
            {
                message << ": hit the cache when it shouldn't";
                return tcu::TestStatus::fail(message.str());
            }

            if (!(ndx == PIPELINE_NDX_DERIVATIVE && !m_param->isCacheDisabled()) &&
                m_pipelineCreationFeedback[ndx].flags &
                    VK_PIPELINE_CREATION_FEEDBACK_BASE_PIPELINE_ACCELERATION_BIT_EXT)
            {
                message << ": feedback indicates base pipeline acceleration when it shouldn't";
                return tcu::TestStatus::fail(message.str());
            }

            if (ndx == PIPELINE_NDX_USE_BLOBS && !m_param->isCacheDisabled() &&
                (m_pipelineCreationFeedback[ndx].flags &
                 VK_PIPELINE_CREATION_FEEDBACK_APPLICATION_PIPELINE_CACHE_HIT_BIT_EXT) == 0)
            {
                message << "\nWarning: Cached pipeline case did not hit the cache";
                cachedPipelineWarning = true;
            }

            if (m_pipelineCreationFeedback[ndx].duration == 0)
            {
                message << "\nWarning: Pipeline creation feedback reports duration spent creating a pipeline was zero "
                           "nanoseconds\n";
                durationZeroWarning = true;
            }

            message << "\n";

            message << "\t\t Hit cache ? \t\t\t"
                    << (m_pipelineCreationFeedback[ndx].flags &
                                VK_PIPELINE_CREATION_FEEDBACK_APPLICATION_PIPELINE_CACHE_HIT_BIT_EXT ?
                            "yes" :
                            "no")
                    << "\n";
            message << "\t\t Base Pipeline Acceleration ? \t"
                    << (m_pipelineCreationFeedback[ndx].flags &
                                VK_PIPELINE_CREATION_FEEDBACK_BASE_PIPELINE_ACCELERATION_BIT_EXT ?
                            "yes" :
                            "no")
                    << "\n";
            message << "\t\t Duration (ns): \t\t" << m_pipelineCreationFeedback[ndx].duration << "\n";

            message << "\t Compute Stage\n";
        }

        // According to the spec:
        // "An implementation should write pipeline creation feedback to pPipelineCreationFeedback and
        //    may write pipeline stage creation feedback to pPipelineStageCreationFeedbacks."
        if (!(m_pipelineStageCreationFeedback[ndx].flags & VK_PIPELINE_CREATION_FEEDBACK_VALID_BIT_EXT))
        {
            // According to the spec:
            // "If the VK_PIPELINE_CREATION_FEEDBACK_VALID_BIT_EXT is not set in flags, an implementation
            //    must not set any other bits in flags, and all other VkPipelineCreationFeedbackEXT data members are undefined."
            if (m_pipelineStageCreationFeedback[ndx].flags)
            {
                std::ostringstream errorMsg;
                errorMsg << getCaseStr(ndx)
                         << ": Creation feedback is not valid for compute stage but there are other flags written";
                return tcu::TestStatus::fail(errorMsg.str());
            }
            message << "\t\t Pipeline Creation Feedback data is not valid\n";
        }
        else
        {
            if (m_param->isCacheDisabled() && m_pipelineStageCreationFeedback[ndx].flags &
                                                  VK_PIPELINE_CREATION_FEEDBACK_APPLICATION_PIPELINE_CACHE_HIT_BIT_EXT)
            {
                std::ostringstream errorMsg;
                errorMsg << getCaseStr(ndx)
                         << ": feedback indicates pipeline compute stage hit cache when it shouldn't";
                return tcu::TestStatus::fail(errorMsg.str());
            }

            if (ndx == PIPELINE_NDX_USE_BLOBS && !m_param->isCacheDisabled() &&
                (m_pipelineStageCreationFeedback[ndx].flags &
                 VK_PIPELINE_CREATION_FEEDBACK_APPLICATION_PIPELINE_CACHE_HIT_BIT_EXT) == 0)
            {
                message << "Warning: pipeline stage did not hit the cache\n";
                cachedPipelineWarning = true;
            }
            if (cachedPipelineWarning && m_pipelineStageCreationFeedback[ndx].flags &
                                             VK_PIPELINE_CREATION_FEEDBACK_APPLICATION_PIPELINE_CACHE_HIT_BIT_EXT)
            {
                // We only set the warning when the pipeline nor the pipeline stages hit the cache. If any of them did, them disable the warning.
                cachedPipelineWarning = false;
            }

            message << "\t\t Hit cache ? \t\t\t"
                    << (m_pipelineStageCreationFeedback[ndx].flags &
                                VK_PIPELINE_CREATION_FEEDBACK_APPLICATION_PIPELINE_CACHE_HIT_BIT_EXT ?
                            "yes" :
                            "no")
                    << "\n";
            message << "\t\t Base Pipeline Acceleration ? \t"
                    << (m_pipelineStageCreationFeedback[ndx].flags &
                                VK_PIPELINE_CREATION_FEEDBACK_BASE_PIPELINE_ACCELERATION_BIT_EXT ?
                            "yes" :
                            "no")
                    << "\n";
            message << "\t\t Duration (ns): \t\t" << m_pipelineStageCreationFeedback[ndx].duration << "\n";
        }

        log << tcu::TestLog::Message << message.str() << tcu::TestLog::EndMessage;
    }

    if (cachedPipelineWarning)
    {
        return tcu::TestStatus(QP_TEST_RESULT_QUALITY_WARNING, "Cached pipeline or stage did not hit the cache");
    }
    if (durationZeroWarning)
    {
        return tcu::TestStatus(
            QP_TEST_RESULT_QUALITY_WARNING,
            "Pipeline creation feedback reports duration spent creating a pipeline was zero nanoseconds");
    }
    return tcu::TestStatus::pass("Pass");
}

ComputeTestInstance::ComputeTestInstance(Context &context, PipelineConstructionType pipelineConstructionType,
                                         const VkDeviceSize ssboSize, const std::vector<SpecConstant> &specConstants,
                                         const std::vector<OffsetValue> &expectedValues, bool packData)
    : TestInstance(context)
    , m_pipelineConstructionType(pipelineConstructionType)
    , m_ssboSize(ssboSize)
    , m_specConstants(specConstants)
    , m_expectedValues(expectedValues)
    , m_packData(packData)
{
}

tcu::TestStatus ComputeTestInstance::iterate(void)
{
    const DeviceInterface &vk       = m_context.getDeviceInterface();
    const VkDevice device           = m_context.getDevice();
    const VkQueue queue             = m_context.getUniversalQueue();
    const uint32_t queueFamilyIndex = m_context.getUniversalQueueFamilyIndex();
    Allocator &allocator            = m_context.getDefaultAllocator();

    // Descriptors

    const BufferWithMemory resultBuffer(vk, device, allocator,
                                        makeBufferCreateInfo(m_ssboSize, VK_BUFFER_USAGE_STORAGE_BUFFER_BIT),
                                        MemoryRequirement::HostVisible);

    const Unique<VkDescriptorSetLayout> descriptorSetLayout(
        DescriptorSetLayoutBuilder()
            .addSingleBinding(VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, VK_SHADER_STAGE_COMPUTE_BIT)
            .build(vk, device));

    const Unique<VkDescriptorPool> descriptorPool(
        DescriptorPoolBuilder()
            .addType(VK_DESCRIPTOR_TYPE_STORAGE_BUFFER)
            .build(vk, device, VK_DESCRIPTOR_POOL_CREATE_FREE_DESCRIPTOR_SET_BIT, 1u));

    const Unique<VkDescriptorSet> descriptorSet(makeDescriptorSet(vk, device, *descriptorPool, *descriptorSetLayout));
    const VkDescriptorBufferInfo descriptorBufferInfo = makeDescriptorBufferInfo(resultBuffer.get(), 0ull, m_ssboSize);

    DescriptorSetUpdateBuilder()
        .writeSingle(*descriptorSet, DescriptorSetUpdateBuilder::Location::binding(0u),
                     VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, &descriptorBufferInfo)
        .update(vk, device);

    // Specialization

    const Specialization specialization(m_specConstants, m_packData);
    const VkSpecializationInfo *pSpecInfo = specialization.getSpecializationInfo();

    // Pipeline

    const PipelineLayoutWrapper pipelineLayout(m_pipelineConstructionType, vk, device, *descriptorSetLayout);
    ComputePipelineWrapper pipeline(vk, device, graphicsToComputeConstructionType(m_pipelineConstructionType),
                                    m_context.getBinaryCollection().get("comp"));
    pipeline.setDescriptorSetLayout(*descriptorSetLayout);
    if (pSpecInfo)
        pipeline.setSpecializationInfo(*pSpecInfo);
    pipeline.buildPipeline();
    const Unique<VkCommandPool> cmdPool(
        createCommandPool(vk, device, VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT, queueFamilyIndex));
    const Unique<VkCommandBuffer> cmdBuffer(makeCommandBuffer(vk, device, *cmdPool));

    beginCommandBuffer(vk, *cmdBuffer);

    pipeline.bind(*cmdBuffer);
    vk.cmdBindDescriptorSets(*cmdBuffer, VK_PIPELINE_BIND_POINT_COMPUTE, *pipelineLayout, 0u, 1u, &descriptorSet.get(),
                             0u, nullptr);

    vk.cmdDispatch(*cmdBuffer, 1u, 1u, 1u);

    {
        const VkBufferMemoryBarrier shaderWriteBarrier = makeBufferMemoryBarrier(
            VK_ACCESS_SHADER_WRITE_BIT, VK_ACCESS_HOST_READ_BIT, *resultBuffer, 0ull, m_ssboSize);

        vk.cmdPipelineBarrier(*cmdBuffer, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, VK_PIPELINE_STAGE_HOST_BIT, 0u, 0u,
                              nullptr, 1u, &shaderWriteBarrier, 0u, nullptr);
    }

    endCommandBuffer(vk, *cmdBuffer);
    submitCommandsAndWait(vk, device, queue, *cmdBuffer);

    // Verify results

    const Allocation &resultAlloc = resultBuffer.getAllocation();
    invalidateAlloc(vk, device, resultAlloc);

    if (verifyValues(m_context.getTestContext().getLog(), resultAlloc.getHostPtr(), m_expectedValues))
        return tcu::TestStatus::pass("Success");
    else
        return tcu::TestStatus::fail("Values did not match");
}

