class ShaderMatrixCase : public ShaderRenderCase
{
public:
    ShaderMatrixCase(tcu::TestContext &testCtx, const std::string &name, const ShaderInput &in0, const ShaderInput &in1,
                     const MatrixOp op, bool isVertexCase);
