                                                                     &properties);
        if (!(properties.bufferFeatures & m_testCase.features))
            TCU_THROW(NotSupportedError, "Format not supported");
        if (m_testCase.bufferAllocationKind == ALLOCATION_KIND_DEDICATED)
        {
