class TextureGatherMinLodTest : public vkt::TestCase
{
public:
    TextureGatherMinLodTest(tcu::TestContext &testCtx, const std::string &name, const GatherParams &params)
        : vkt::TestCase(testCtx, name)
        , m_params(params)
