            caps.addFeature(&VkPhysicalDeviceImageViewMinLodFeaturesEXT::minLod);
            caps.addFeature(&VkPhysicalDeviceRobustness2FeaturesEXT::robustBufferAccess2);
            caps.addFeature(&VkPhysicalDeviceFeatures::robustBufferAccess);
        }
