class ShaderTextureFunctionCase : public ShaderRenderCase
{
public:
    ShaderTextureFunctionCase(tcu::TestContext &testCtx, const std::string &name, const TextureLookupSpec &lookup,
                              const TextureSpec &texture, TexEvalFunc evalFunc, bool isVertexCase);
    virtual ~ShaderTextureFunctionCase(void);

    virtual TestInstance *createInstance(Context &context) const;
    virtual void checkSupport(Context &context) const;

protected:
    const TextureLookupSpec m_lookupSpec;
    const TextureSpec m_textureSpec;
    const TexLookupParams m_lookupParams;

    void initShaderSources(void);
};



// === Member function implementations ===

ShaderTextureFunctionCase::ShaderTextureFunctionCase(tcu::TestContext &testCtx, const std::string &name,
                                                     const TextureLookupSpec &lookup, const TextureSpec &texture,
                                                     TexEvalFunc evalFunc, bool isVertexCase)
    : ShaderRenderCase(testCtx, name, isVertexCase, new TexLookupEvaluator(evalFunc, m_lookupParams), NULL, NULL)
    , m_lookupSpec(lookup)
    , m_textureSpec(texture)
{
    initShaderSources();
}

ShaderTextureFunctionCase::~ShaderTextureFunctionCase(void)
{
}

TestInstance *ShaderTextureFunctionCase::createInstance(Context &context) const
{
    DE_ASSERT(m_evaluator);
    DE_ASSERT(m_uniformSetup);
    return new ShaderTextureFunctionInstance(context, m_isVertexCase, *m_evaluator, *m_uniformSetup, m_lookupSpec,
                                             m_textureSpec, m_lookupParams);
}

void ShaderTextureFunctionCase::checkSupport(Context &context) const
{
    checkMutableComparisonSamplersSupport(context, m_textureSpec);

    if (m_lookupSpec.pcOffset)
        context.requireDeviceFunctionality("VK_KHR_maintenance8");
}

void ShaderTextureFunctionCase::initShaderSources(void)
{
    Function function = m_lookupSpec.function;
    bool isVtxCase    = m_isVertexCase;
    bool isProj       = functionHasProj(function);
    bool isGrad       = functionHasGrad(function);
    bool isShadow     = m_textureSpec.sampler.compare != tcu::Sampler::COMPAREMODE_NONE;
    bool is2DProj4    = !isShadow && m_textureSpec.type == TEXTURETYPE_2D &&
                     (function == FUNCTION_TEXTUREPROJ || function == FUNCTION_TEXTUREPROJLOD ||
                      function == FUNCTION_TEXTUREPROJGRAD);
    bool is1DProj4 = !isShadow && m_textureSpec.type == TEXTURETYPE_1D &&
                     (function == FUNCTION_TEXTUREPROJ || function == FUNCTION_TEXTUREPROJLOD ||
                      function == FUNCTION_TEXTUREPROJGRAD);
    bool isIntCoord     = function == FUNCTION_TEXELFETCH;
    bool hasLodBias     = functionHasLod(m_lookupSpec.function) || m_lookupSpec.useBias;
    int texCoordComps   = m_textureSpec.type == TEXTURETYPE_1D                                               ? 1 :
                          m_textureSpec.type == TEXTURETYPE_1D_ARRAY || m_textureSpec.type == TEXTURETYPE_2D ? 2 :
                          m_textureSpec.type == TEXTURETYPE_CUBE_ARRAY                                       ? 4 :
                                                                                                               3;
    int extraCoordComps = (isProj ? (is2DProj4 ? 2 : (is1DProj4 ? 3 : 1)) : 0) +
                          (isShadow ? (m_textureSpec.type == TEXTURETYPE_1D ? 2 : 1) : 0);
    const bool isCubeArrayShadow = isShadow && m_textureSpec.type == TEXTURETYPE_CUBE_ARRAY;
    glu::DataType coordType      = glu::getDataTypeFloatVec(isCubeArrayShadow ? 4 : texCoordComps + extraCoordComps);
    glu::Precision coordPrec     = glu::PRECISION_HIGHP;
    const char *coordTypeName    = glu::getDataTypeName(coordType);
    const char *coordPrecName    = glu::getPrecisionName(coordPrec);
    tcu::TextureFormat texFmt    = glu::mapGLInternalFormat(m_textureSpec.format);
    glu::DataType samplerType    = glu::TYPE_LAST;
    glu::DataType gradType       = m_textureSpec.type == TEXTURETYPE_1D || m_textureSpec.type == TEXTURETYPE_1D_ARRAY ?
                                       glu::TYPE_FLOAT :
                                   m_textureSpec.type == TEXTURETYPE_3D || m_textureSpec.type == TEXTURETYPE_CUBE_MAP ||
                                     m_textureSpec.type == TEXTURETYPE_CUBE_ARRAY ?
                                       glu::TYPE_FLOAT_VEC3 :
                                       glu::TYPE_FLOAT_VEC2;
    const char *gradTypeName     = glu::getDataTypeName(gradType);
    const char *baseFuncName     = nullptr;

    DE_ASSERT(!isGrad || !hasLodBias);

    switch (m_textureSpec.type)
    {
    case TEXTURETYPE_2D:
        samplerType = isShadow ? glu::TYPE_SAMPLER_2D_SHADOW : glu::getSampler2DType(texFmt);
        break;
    case TEXTURETYPE_CUBE_MAP:
        samplerType = isShadow ? glu::TYPE_SAMPLER_CUBE_SHADOW : glu::getSamplerCubeType(texFmt);
        break;
    case TEXTURETYPE_2D_ARRAY:
        samplerType = isShadow ? glu::TYPE_SAMPLER_2D_ARRAY_SHADOW : glu::getSampler2DArrayType(texFmt);
        break;
    case TEXTURETYPE_3D:
        DE_ASSERT(!isShadow);
        samplerType = glu::getSampler3DType(texFmt);
        break;
    case TEXTURETYPE_1D:
        samplerType = isShadow ? glu::TYPE_SAMPLER_1D_SHADOW : glu::getSampler1DType(texFmt);
        break;
    case TEXTURETYPE_1D_ARRAY:
        samplerType = isShadow ? glu::TYPE_SAMPLER_1D_ARRAY_SHADOW : glu::getSampler1DArrayType(texFmt);
        break;
    case TEXTURETYPE_CUBE_ARRAY:
        samplerType = isShadow ? glu::TYPE_SAMPLER_CUBE_ARRAY_SHADOW : glu::getSamplerCubeArrayType(texFmt);
        break;
    default:
        DE_ASSERT(false);
    }

    switch (m_lookupSpec.function)
    {
    case FUNCTION_TEXTURE:
        baseFuncName = "texture";
        break;
    case FUNCTION_TEXTUREPROJ:
        baseFuncName = "textureProj";
        break;
    case FUNCTION_TEXTUREPROJ2:
        baseFuncName = "textureProj";
        break;
    case FUNCTION_TEXTUREPROJ3:
        baseFuncName = "textureProj";
        break;
    case FUNCTION_TEXTURELOD:
        baseFuncName = "textureLod";
        break;
    case FUNCTION_TEXTUREPROJLOD:
        baseFuncName = "textureProjLod";
        break;
    case FUNCTION_TEXTUREPROJLOD2:
        baseFuncName = "textureProjLod";
        break;
    case FUNCTION_TEXTUREPROJLOD3:
        baseFuncName = "textureProjLod";
        break;
    case FUNCTION_TEXTUREGRAD:
        baseFuncName = "textureGrad";
        break;
    case FUNCTION_TEXTUREPROJGRAD:
        baseFuncName = "textureProjGrad";
        break;
    case FUNCTION_TEXTUREPROJGRAD2:
        baseFuncName = "textureProjGrad";
        break;
    case FUNCTION_TEXTUREPROJGRAD3:
        baseFuncName = "textureProjGrad";
        break;
    case FUNCTION_TEXELFETCH:
        baseFuncName = "texelFetch";
        break;
    default:
        DE_ASSERT(false);
    }

    std::ostringstream vert;
    std::ostringstream frag;
    std::ostringstream &op = isVtxCase ? vert : frag;

    const auto pcOffsetExt = "#extension GL_EXT_texture_offset_non_const : enable\n";

    vert << "#version 450 core\n"
         << (m_lookupSpec.pcOffset && isVtxCase ? pcOffsetExt : "")
         << "layout(location = 0) in highp vec4 a_position;\n"
         << "layout(location = 4) in " << coordPrecName << " " << coordTypeName << " a_in0;\n";

    if (isGrad)
    {
        vert << "layout(location = 5) in " << coordPrecName << " " << gradTypeName << " a_in1;\n";
        vert << "layout(location = 6) in " << coordPrecName << " " << gradTypeName << " a_in2;\n";
    }
    else if (hasLodBias)
        vert << "layout(location = 5) in " << coordPrecName << " float a_in1;\n";

    frag << "#version 450 core\n";

    if (m_lookupSpec.useClamp)
        frag << "#extension GL_ARB_sparse_texture_clamp : require\n";

    if (m_lookupSpec.pcOffset && !isVtxCase)
        frag << pcOffsetExt;

    frag << "layout(location = 0) out mediump vec4 o_color;\n";

    if (isVtxCase)
    {
        vert << "layout(location = 0) out mediump vec4 v_color;\n";
        frag << "layout(location = 0) in mediump vec4 v_color;\n";
    }
    else
    {
        vert << "layout(location = 0) out " << coordPrecName << " " << coordTypeName << " v_texCoord;\n";
        frag << "layout(location = 0) in " << coordPrecName << " " << coordTypeName << " v_texCoord;\n";

        if (isGrad)
        {
            vert << "layout(location = 1) out " << coordPrecName << " " << gradTypeName << " v_gradX;\n";
            vert << "layout(location = 2) out " << coordPrecName << " " << gradTypeName << " v_gradY;\n";
            frag << "layout(location = 1) in " << coordPrecName << " " << gradTypeName << " v_gradX;\n";
            frag << "layout(location = 2) in " << coordPrecName << " " << gradTypeName << " v_gradY;\n";
        }
        else if (hasLodBias)
        {
            vert << "layout(location = 1) out " << coordPrecName << " float v_lodBias;\n";
            frag << "layout(location = 1) in " << coordPrecName << " float v_lodBias;\n";
        }
    }

    // Uniforms
    op << "layout(set = 0, binding = 0) uniform highp " << glu::getDataTypeName(samplerType) << " u_sampler;\n"
       << "layout(set = 0, binding = 1) uniform buf0 { highp vec4 u_scale; };\n"
       << "layout(set = 0, binding = 2) uniform buf1 { highp vec4 u_bias; };\n";

    if (m_lookupSpec.pcOffset)
        op << "layout(push_constant, std430) uniform PCBlock { ivec3 offset; } pc;\n";

    vert << "out gl_PerVertex {\n"
         << "\tvec4 gl_Position;\n"
         << "};\n";

    vert << "\nvoid main()\n{\n"
         << "\tgl_Position = a_position;\n";
    frag << "\nvoid main()\n{\n";

    if (isVtxCase)
        vert << "\tv_color = ";
    else
        frag << "\to_color = ";

    // Op.
    {
        const char *texCoord = isVtxCase ? "a_in0" : "v_texCoord";
        const char *gradX    = isVtxCase ? "a_in1" : "v_gradX";
        const char *gradY    = isVtxCase ? "a_in2" : "v_gradY";
        const char *lodBias  = isVtxCase ? "a_in1" : "v_lodBias";

        op << "vec4(" << baseFuncName;
        if (m_lookupSpec.useOffset)
            op << "Offset";
        if (m_lookupSpec.useClamp)
            op << "ClampARB";
        op << "(u_sampler, ";

        if (isIntCoord)
            op << glu::getDataTypeName(glu::getDataTypeIntVec(texCoordComps + extraCoordComps)) << "(";

        op << texCoord;

        if (isIntCoord)
            op << ")";

        if (isGrad)
            op << ", " << gradX << ", " << gradY;

        if (functionHasLod(function))
        {
            if (isIntCoord)
                op << ", int(" << lodBias << ")";
            else
                op << ", " << lodBias;
        }

        if (m_lookupSpec.useOffset)
        {
            int offsetComps = m_textureSpec.type == TEXTURETYPE_1D || m_textureSpec.type == TEXTURETYPE_1D_ARRAY ? 1 :
                              m_textureSpec.type == TEXTURETYPE_3D                                               ? 3 :
                                                                                                                   2;

            op << ", " << glu::getDataTypeName(glu::getDataTypeIntVec(offsetComps)) << "(";
            for (int ndx = 0; ndx < offsetComps; ndx++)
            {
                if (ndx != 0)
                    op << ", ";
                if (m_lookupSpec.pcOffset)
                    op << "pc.offset."
                       << "xyzw"[ndx];
                else
                    op << m_lookupSpec.offset[ndx];
            }
            op << ")";
        }

        if (m_lookupSpec.useClamp)
            op << ", float(" << m_lookupSpec.lodClamp << ")";

        if (isCubeArrayShadow && m_lookupSpec.function == FUNCTION_TEXTURE)
            op << ", " << texCoord << ".w";

        if (m_lookupSpec.useBias)
            op << ", " << lodBias;

        op << ")";

        if (isShadow)
            op << ", 0.0, 0.0, 1.0)";
        else
            op << ")*u_scale + u_bias";

        op << ";\n";
    }

    if (isVtxCase)
        frag << "\to_color = v_color;\n";
    else
    {
        vert << "\tv_texCoord = a_in0;\n";

        if (isGrad)
        {
            vert << "\tv_gradX = a_in1;\n";
            vert << "\tv_gradY = a_in2;\n";
        }
        else if (hasLodBias)
            vert << "\tv_lodBias = a_in1;\n";
    }

    vert << "}\n";
    frag << "}\n";

    m_vertShaderSource = vert.str();
    m_fragShaderSource = frag.str();

    if (m_lookupSpec.pcOffset)
    {
        vk::ShaderBuildOptions buildOptions;
        buildOptions.flags |= vk::ShaderBuildOptions::FLAG_ALLOW_NON_CONST_OFFSETS;

        de::MovePtr<vk::ShaderBuildOptions> &targetOptions =
            (isVtxCase ? m_vertShaderBuildOptions : m_fragShaderBuildOptions);
        targetOptions = de::MovePtr<vk::ShaderBuildOptions>(new vk::ShaderBuildOptions(buildOptions));
    }
}

