        expected_dataui[8]  = UVec4(37, 38, 39, 1);
        expected_dataui[9]  = UVec4(41, 42, 0, 1);
        expected_dataui[10] = UVec4(45, 0, 0, 1);
        expected_dataui[11] = UVec4(102, 103, 104, 105);
        return BasicInputIBase::Run();
    }
};

