                        << tcu::TestLog::Message << "Incorrect framebuffer color at pixel (" << x << " " << y
                        << "). Color is (" << fb[idx][0] << " " << fb[idx][1] << " " << fb[idx][2]
                        << "). Color should be (" << expected[0] << " " << expected[1] << " " << expected[2] << ")"
                        << tcu::TestLog::EndMessage;
