    {
        glUseProgram(0);
        glDeleteProgram(m_program);
        glDeleteBuffers(8, m_storage_buffer);
        if (stage != compute)
            glDeleteVertexArrays(1, &m_vertex_array);
        return NO_ERROR;
    }
