        {PipelineType::VERT_OUT_FRAG_IN, {0, 1, 0}},
        {PipelineType::VERT_OUT_TESC_IN_TESE_FRAG, {0, 0, 1}},
        {PipelineType::VERT_TESC_TESE_OUT_FRAG_IN, {0, 1, 0}},
