    static const GLchar *vertex_shader_template = "VERSION\n"
                                                  "\n"
                                                  "out vec4 vs_tcs_result;\n"
                                                  "\n"
                                                  "VARIABLE_DECLARATION;\n"
                                                  "VARIABLE_DECLARATION;\n"
