        m_data.emplace_back(tcu::Vec4(1.0f, -1.0f, 1.0f, 1.0f), tcu::Vec4(1.0f), -1);
        m_data.emplace_back(tcu::Vec4(-1.0f, -1.0f, 1.0f, 1.0f), tcu::Vec4(1.0f), -1);

        if (!isIndexed() || isBaseInstOnly())
