    MatrixStoreFlags m_matrixStoreFlag;
    std::string m_computeShaderSrc;
    bool m_usePhysStorageBuffer;

private:
    SSBOLayoutCase(const SSBOLayoutCase &);
    SSBOLayoutCase &operator=(const SSBOLayoutCase &);

    BufferLayout m_refLayout;
