    std::string result;

    /* Skip for compute shader */
    if (Utils::Shader::FRAGMENT != stage)
    {
        result = "";
    }
    else
    {
        result = "chichi = vec4(0, 0, 1, 1);\n"
                 "    goku   = vec4(0, 0, 0, 1);\n"
                 "    goten  = vec4(0, 1, 0, 1);\n"
                 "    gohan  = vec4(1, 0, 0, 1);\n";
