                                               "precision highp float;\n"
                                               "\n"
                                               "in vec4 vs_in_position;\n"
                                               "\n"
                                               "void main()\n"
                                               "{\n"
                                               "    gl_Position = vs_in_position;\n"
                                               "}\n";

