        tese << "#version 450\n"
             << "layout(quads, cw, fractional_odd_spacing) in;\n"
             << "\n"
             << "layout(location = 5) patch in vec4 col0;\n"
             << "\n"
             << "layout(location = 0) out vec4 col0_fs;\n"
             << "\n"
             << "void main()\n"
             << "{\n"
             << "    col0_fs = col0;\n"
             << "    gl_Position = vec4(gl_TessCoord.xy * 2. - 1., 0, 1);\n"
