        frag << "#version 450\n"
             << "layout(location = 0) in vec4 col0_fs;\n"
             << "layout(location = 0) out vec4 color;\n"
             << "\n"
             << "void main()\n"
             << "{\n"
             << "    color = vec4(abs(col0_fs.x - 0.53455) < 0.01,\n"
