                }
            }
#endif // CTS_USES_VULKANSC
        }
        if (m_atomicOp == ATOMIC_OP_EXCHANGE)
        {
            if (m_shaderType.isSharedLike())
            {
                if (!ctx.getShaderAtomicFloatFeaturesEXT().shaderSharedFloat32Atomics)
