            m_context.getTestContext().getLog()
                << tcu::TestLog::Message
                << "GL_ATOMIC_COUNTER_BUFFER_SIZE state is incorrect (GetInteger64i_v, is: " << static_cast<GLint>(i64)
                << ", expected: " << static_cast<GLint>(size) << ", index: " << index << ")"
