class AtomicOperationCase : public TestCase
{
public:
    AtomicOperationCase(tcu::TestContext &testCtx, const char *name, AtomicShaderType type, DataType dataType,
                        AtomicOperation atomicOp);
    virtual ~AtomicOperationCase(void);

